1	namespace FutureClassroom.Core.Data;
2	
3	public class Course {
4	    public int Id { get; set; }
5	    public string CourseKey { get; set; } = string.Empty;   // e.g. 1142_502 20002_04
6	    public string CourseId { get; set; } = string.Empty;    // e.g. 502 20002
7	    public string Serial { get; set; } = string.Empty;      // e.g. 47355
8	    public string Name { get; set; } = string.Empty;
9	    public string? NameEn { get; set; }
10	    public string Semester { get; set; } = string.Empty;    // e.g. 1142
11	    public string? Section { get; set; }                    // e.g. 04
12	    public string TeacherId { get; set; } = string.Empty;
13	    public string TeacherName { get; set; } = string.Empty;
14	    public int TotalStudentQuota { get; set; }
15	    public string? ClassroomName { get; set; }      // e.g. 綜401
16	    public string? ClassroomLocation { get; set; }  // e.g. 綜合教學館四樓
17	    public string? BuildingName { get; set; }        // e.g. 綜合教學館
18	    public string? BuildingId { get; set; }          // e.g. AT2049
19	    public string? SchedulesJson { get; set; }        // JSON: [{"weekday":1,"intervals":["3","4"]}]
20	    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
21	    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
22	
23	    public List<Lesson> Lessons { get; set; } = [];
24	}
