1	using System.Security.Claims;
2	using FutureClassroom.Api.Models;
3	
4	namespace FutureClassroom.Api.Endpoints;
5	
6	public static class UserEndpoints {
7	    public static void MapUserApi(this IEndpointRouteBuilder app) {
8	
9	        // GET /user
10	        // find or create user in database, return user info
11	        app.MapGet("/user", (HttpContext context) => {
12	            var id = context.User.FindFirst("StudentId")?.Value;
13	            var name = context.User.FindFirst(ClaimTypes.Name)?.Value;
14	            var department = context.User.FindFirst("Major")?.Value;
15	            var role = context.User.FindFirst("UserType")?.Value;
16	
17	            if (string.IsNullOrEmpty(id) || string.IsNullOrEmpty(role))
18	                return ApiErrors.Unauthorized();
19	
20	            return Results.Ok(new UserProfileResponse(
21	                UserId: id,
22	                Name: name ?? "",
23	                Major: department,
24	                Role: role,
25	                LastUpdatedAt: DateTime.UtcNow
26	            ));
27	        }).RequireAuthorization();
28	    }
29	}
