1	using Microsoft.AspNetCore.Authentication.Cookies;
2	
3	namespace FutureClassroom.Api.Auth;
4	
5	public class Saml2CookieManager : ICookieManager
6	{
7	    private readonly ChunkingCookieManager _inner = new ChunkingCookieManager();
8	    private readonly PathString _saml2CookiePath;
9	
10	    public Saml2CookieManager(string? baseUrlPath)
11	    {        
12	        _saml2CookiePath = string.IsNullOrEmpty(baseUrlPath)
13	            ? new PathString("/")
14	            : new PathString("/" + baseUrlPath);
15	    }
16	
17	    public string? GetRequestCookie(HttpContext context, string key)
18	    {
19	        return _inner.GetRequestCookie(context, key);
20	    }
21	
22	    public void AppendResponseCookie(HttpContext context, string key, string value, CookieOptions options)
23	    {
24	        if (key.StartsWith("Saml2.", StringComparison.OrdinalIgnoreCase))
25	        {
26	            options.Path = _saml2CookiePath;
27	            options.SameSite = SameSiteMode.None;
28	            options.Secure = true;
29	        }
30	
31	        _inner.AppendResponseCookie(context, key, value, options);
32	    }
33	
34	    public void DeleteCookie(HttpContext context, string key, CookieOptions options)
35	    {
36	        if (key.StartsWith("Saml2.", StringComparison.OrdinalIgnoreCase))
37	        {
38	            options.Path = _saml2CookiePath;
39	            options.SameSite = SameSiteMode.None;
40	            options.Secure = true;
41	        }
42	
43	        _inner.DeleteCookie(context, key, options);
44	    }
45	}
