1	using FutureClassroom.Api.Services;
2	using FutureClassroom.Core.Helpers;
3	
4	namespace FutureClassroom.Api.Endpoints;
5	
6	public static class CourseEndpoints
7	{
8	    public static void MapNTUCourseApi(this WebApplication app)
9	    {
10	        var isDev = app.Environment.IsDevelopment();
11	        var group = app.MapGroup("/courses");
12	
13	        if (!isDev)
14	        {
15	            group.RequireAuthorization();
16	        }
17	
18	        // GET /courses
19	        // Now
20	        // 所有課程
21	
22	        // 未來可能:
23	        // 只能看到自己授課的課程
24	
25	        // 排程: 自動從 NTU Course API 抓取資料並更新資料庫
26	
27	        /// <summary>
28	        /// 所有課程
29	        /// </summary>
30	        /// <param name="semester"></param>
31	        group.MapGet("/", async (HttpContext context, CourseService courseService, string? semester) =>
32	        {
33	
34	            if (semester is not null && (semester.Length != 4 || !semester.All(char.IsDigit)))
35	                return ApiErrors.InvalidParameter();
36	
37	
38	
39	            try
40	            {
41	
42	                // // phase 1: 先不做權限控管，直接回傳所有未來教室課程資料 //////////////////////////
43	                // // TODO: 之後要改成只能看到自己授課的課程
44	
45	                // var teacherName = "林以凡"; 
46	                // // 宜桓、尹男林以凡、謝宜桓、黃尹男
47	
48	                // var location = "綜401";
49	                ///////////////////////////////////////////////////////////////////////
50	                var response = await courseService.GetCoursesAsync(semester: semester);
51	
52	                if (response.Semesters.Count == 0)
53	                    return ApiErrors.NotFound("no_courses_found", "No courses found for the specified semester.");
54	
55	                return Results.Ok(response);
56	            }
57	            catch (Exception ex)
58	            {
59	                Console.WriteLine($"[CourseEndpoints] Exception: {ex}");
60	                return ApiErrors.InternalError();
61	            }
62	        }).WithSummary("所有課程");
63	
64	        /// <summary>
65	        /// 課程週覽
66	        /// </summary>
67	        /// <param name="courseKey"></param>
68	        group.MapGet("/{courseKey}/lessons", async (
69	            string courseKey,
70	            CourseService courseService
71	        ) =>
72	        {
73	            courseKey = CourseHelper.DecodePathValue(courseKey);
74	
75	            if (string.IsNullOrWhiteSpace(courseKey) || courseKey.Split('_').Length < 2)
76	                return ApiErrors.InvalidParameter();
77	
78	            try
79	            {
80	                var result = await courseService.GetCourseLessonsAsync(courseKey);
81	                return Results.Ok(result);
82	            }
83	            catch (KeyNotFoundException)
84	            {
85	                return ApiErrors.NotFound("no_courses_found", "No courses found for the specified course key.");
86	            }
87	        }).WithSummary("課程週覽");
88	    }
89	}
