1	using Amazon.S3;
2	using FutureClassroom.Core.Data;
3	using FutureClassroom.Core.Factory;
4	using FutureClassroom.Job.Jobs;
5	using FutureClassroom.Job.Jobs.Implement;
6	using FutureClassroom.Job.Options;
7	using Hangfire;
8	using Hangfire.PostgreSql;
9	using Microsoft.EntityFrameworkCore;
10	
11	var builder = Host.CreateApplicationBuilder(args);
12	
13	var connectionString = builder.Configuration.GetConnectionString("Default")
14	    ?? throw new InvalidOperationException("Connection string 'Default' not found.");
15	
16	builder.Services.AddScoped<IVideoScreenshot, VideoScreenshot>();
17	builder.Services.AddScoped<ICourseLessonSync, CourseLessonSync>();
18	builder.Services.AddScoped<IDepartmentSync, DepartmentSync>();
19	
20	builder.Services.Configure<NtuCourseApiOptions>(builder.Configuration.GetSection("NtuCourseApi"));
21	builder.Services.AddHttpClient("NTUCourseApi").ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler
22	{
23	    SslOptions = new System.Net.Security.SslClientAuthenticationOptions
24	    {
25	        RemoteCertificateValidationCallback = (_, _, _, _) => true
26	    }
27	});
28	
29	builder.Services.AddDbContextFactory<AppDbContext>(options =>
30	    options.UseNpgsql(connectionString));
31	
32	builder.Services.AddKeyedSingleton<IAmazonS3>("minio", (_, _) =>
33	{
34	    var minioConfig = builder.Configuration.GetSection("MinIO");
35	    return new AmazonS3Client(minioConfig["AccessKey"] ?? "", minioConfig["SecretKey"] ?? "", new AmazonS3Config
36	    {
37	        ServiceURL = minioConfig["ServiceUrl"],
38	        ForcePathStyle = true,
39	        AuthenticationRegion = "us-east-1",
40	        HttpClientFactory = new BypassSslHttpClientFactory()
41	    });
42	});
43	
44	builder.Services.AddKeyedSingleton<IAmazonS3>("s3", (_, _) =>
45	{
46	    var s3Config = builder.Configuration.GetSection("S3");
47	    return new AmazonS3Client(s3Config["AccessKey"] ?? "", s3Config["SecretKey"] ?? "", new AmazonS3Config
48	    {
49	        ServiceURL = s3Config["ServiceUrl"],
50	        ForcePathStyle = true,
51	        AuthenticationRegion = "us-east-1",
52	        HttpClientFactory = new BypassSslHttpClientFactory()
53	    });
54	});
55	
56	builder.Services.AddHangfire(config => config
57	    .SetDataCompatibilityLevel(CompatibilityLevel.Version_180)
58	    .UseSimpleAssemblyNameTypeSerializer()
59	    .UseRecommendedSerializerSettings()
60	    .UsePostgreSqlStorage(options => options.UseNpgsqlConnection(connectionString)));
61	
62	builder.Services.AddHangfireServer();
63	
64	var app = builder.Build();
65	
66	var recurringJobManager = app.Services.GetRequiredService<IRecurringJobManager>();
67	recurringJobManager.AddOrUpdate<IVideoScreenshot>(
68	    "video-screenshot-job",
69	    job => job.ExecuteAsync(),
70	    Cron.Hourly());
71	
72	recurringJobManager.AddOrUpdate<ICourseLessonSync>(
73	    "course-lesson-sync-job",
74	    job => job.ExecuteAsync(),
75	    Cron.Daily(3));
76	
77	recurringJobManager.AddOrUpdate<IDepartmentSync>(
78	    "department-sync-job",
79	    job => job.ExecuteAsync(),
80	    Cron.Daily(4));
81	
82	try
83	{
84	    using var scope = app.Services.CreateScope();
85	    var dbFactory = scope.ServiceProvider.GetRequiredService<IDbContextFactory<AppDbContext>>();
86	    using var db = dbFactory.CreateDbContext();
87	    var bootstrapClient = app.Services.GetRequiredService<IBackgroundJobClient>();
88	    if (!db.Departments.Any() || !db.Departments.Any(d => d.ShortNameZh != null))
89	    {
90	        bootstrapClient.Enqueue<IDepartmentSync>(job => job.ExecuteAsync());
91	    }
92	    if (db.Courses.Any(c => string.IsNullOrEmpty(c.NameEn)))
93	    {
94	        bootstrapClient.Enqueue<ICourseLessonSync>(job => job.ExecuteAsync());
95	    }
96	}
97	catch (Exception ex)
98	{
99	    var logger = app.Services.GetRequiredService<ILoggerFactory>().CreateLogger("DepartmentSyncBootstrap");
100	    logger.LogWarning(ex, "無法檢查 Departments 是否為空，略過啟動時同步。請確認已套用 migration。");
101	}
102	
103	#if DEBUG
104	
105	var backgroundJobClient = app.Services.GetRequiredService<IBackgroundJobClient>();
106	backgroundJobClient.Enqueue<IVideoScreenshot>(job => job.ExecuteAsync());
107	
108	#endif
109	
110	app.Run();
