1	using System.Net.Http.Json;
2	using System.Text.Json;
3	using System.Text.Json.Serialization;
4	using FutureClassroom.Core.Data;
5	using FutureClassroom.Core.Helpers;
6	using FutureClassroom.Job.Options;
7	using Microsoft.EntityFrameworkCore;
8	using Microsoft.Extensions.Options;
9	
10	namespace FutureClassroom.Job.Jobs.Implement;
11	
12	/// <summary>
13	/// 同步台大課程資料與堂次資料（先同步課程，再依課程同步堂次）
14	/// </summary>
15	public class CourseLessonSync : ICourseLessonSync
16	{
17	    private readonly ILogger<CourseLessonSync> _logger;
18	    private readonly IDbContextFactory<AppDbContext> _dbFactory;
19	    private readonly IHttpClientFactory _httpClientFactory;
20	    private readonly string _courseSearchUrl;
21	    private readonly string _courseApiBase;
22	    private readonly string _coursePath;
23	    private readonly string _courseNameEnApiBase;
24	
25	    // Q: Location 有可能有兩個，神經與行為模型建構有兩間教室
26	    private static readonly (string Teacher, string Name, string Location)[] Targets =
27	    [
28	        ("黃尹男", "應用力學2", "綜401"),
29	        ("陳怡秀", "氣候變遷對策：地球急轉彎", "綜401"),
30	        ("林以凡", "工程數學下", "綜401"),
31	        ("黃從仁", "神經與行為模型建構", "綜401"),
32	    ];
33	
34	    public CourseLessonSync(ILogger<CourseLessonSync> logger, IDbContextFactory<AppDbContext> dbFactory, IHttpClientFactory httpClientFactory, IOptions<NtuCourseApiOptions> options)
35	    {
36	        _logger = logger;
37	        _dbFactory = dbFactory;
38	        _httpClientFactory = httpClientFactory;
39	        _courseSearchUrl = $"{options.Value.BaseUrl.TrimEnd('/')}/{options.Value.SearchPath.TrimStart('/')}";
40	        _courseApiBase = options.Value.BaseUrl.TrimEnd('/');
41	        _coursePath = options.Value.CoursePath.TrimStart('/');
42	        _courseNameEnApiBase = string.IsNullOrWhiteSpace(options.Value.DeptsBaseUrl) // 課程英文名稱要用新課程網 prod 才撈得到
43	            ? _courseApiBase
44	            : options.Value.DeptsBaseUrl.TrimEnd('/');
45	    }
46	
47	    public async Task ExecuteAsync()
48	    {
49	        using var httpClient = _httpClientFactory.CreateClient("NTUCourseApi");
50	        await RunStepAsync(() => SyncCoursesAsync(httpClient), "課程", "所有指定老師的課程同步完成。");
51	        await RunStepAsync(() => SyncEnglishNamesAsync(httpClient), "英文課名", "所有課程英文名稱同步完成。");
52	        await RunStepAsync(() => SyncLessonsAsync(httpClient), "堂次", "所有課程堂次同步完成。");
53	    }
54	
55	    private async Task<bool> RunStepAsync(Func<Task> step, string stepName, string successMessage)
56	    {
57	        _logger.LogInformation("開始同步{StepName}資料...", stepName);
58	        try
59	        {
60	            await step();
61	            _logger.LogInformation("{SuccessMessage}", successMessage);
62	            return true;
63	        }
64	        catch (Exception ex)
65	        {
66	            _logger.LogError(ex, "同步{StepName}過程中發生未預期的錯誤", stepName);
67	            return false;
68	        }
69	    }
70	
71	    /// <summary>
72	    /// Course sync
73	    /// </summary>
74	    /// <param name="httpClient"></param>
75	    /// <returns></returns>
76	    private async Task SyncCoursesAsync(HttpClient httpClient)
77	    {
78	
79	        foreach (var (teacher, name, location) in Targets)
80	        {
81	            _logger.LogInformation("正在抓取 {Teacher} 的「{Name}」...", teacher, name);
82	
83	            var requestBody = new
84	            {
85	                batchSize = 100,
86	                pageIndex = 0,
87	                sorting = "correlation",
88	                query = new
89	                {
90	                    keyword = name,
91	                    teacherKeyword = teacher,
92	                    locationKeyword = location,
93	                    excludedKeywords = Array.Empty<string>(),
94	                    time = new int[][] { [], [], [], [], [], [] },
95	                    isFullYear = (bool?)null,
96	                    timeStrictMatch = false,
97	                    enrollMethods = Array.Empty<string>(),
98	                    isEnglishTaught = false,
99	                    isDistanceLearning = false,
100	                    hasChanged = false,
101	                    isAdditionalCourse = false,
102	                    noPrerequisite = false,
103	                    departments = Array.Empty<string>(),
104	                    isCompulsory = (bool?)null
105	                }
106	            };
107	
108	            var response = await httpClient.PostAsJsonAsync(_courseSearchUrl, requestBody);
109	            if (!response.IsSuccessStatusCode) continue;
110	
111	            var result = await response.Content.ReadFromJsonAsync<NtuApiResult>();
112	            if (result?.Courses == null || result.Courses.Count == 0)
113	            {
114	                _logger.LogWarning("API 未搜到課程: {Teacher} {Name}", teacher, name);
115	                continue;
116	            }
117	
118	            await using var db = await _dbFactory.CreateDbContextAsync();
119	
120	            foreach (var item in result.Courses)
121	            {
122	                if (!item.Name.Equals(name, StringComparison.OrdinalIgnoreCase))
123	                    continue;
124	
125	                var semester = item.Semester.Replace("-", "");
126	                var courseKey = $"{semester}_{item.Code}_{item.Class ?? ""}";
127	                var classroom = item.Schedules?.FirstOrDefault()?.Classroom;
128	
129	                var course = await db.Courses.FirstOrDefaultAsync(c => c.CourseKey == courseKey);
130	                if (course == null)
131	                {
132	                    course = new Course { CourseKey = courseKey, CreatedAt = DateTime.UtcNow };
133	                    db.Courses.Add(course);
134	                }
135	
136	                course.CourseId = item.Code;
137	                course.Serial = item.Serial;
138	                course.Name = item.Name;
139	                var nameEn = await FetchEnglishNameAsync(httpClient, semester, item.Serial);
140	                if (nameEn != null)
141	                    course.NameEn = nameEn;
142	                course.Semester = semester;
143	                course.Section = item.Class;
144	                course.TeacherId = item.Teacher?.Id ?? "Unknown";
145	                course.TeacherName = item.Teacher?.Name ?? "Unknown";
146	                course.TotalStudentQuota = item.TotalStudentQuota;
147	                course.ClassroomName = classroom?.Name;
148	                course.ClassroomLocation = classroom?.Location;
149	                course.BuildingName = classroom?.BuildingName;
150	                course.BuildingId = classroom?.BuildingId;
151	                course.SchedulesJson = JsonSerializer.Serialize(
152	                    (item.Schedules ?? []).Select(s =>
153	                    {
154	                        var sorted = s.Intervals.Order().ToList();
155	                        return new
156	                        {
157	                            weekday = s.Weekday.ToString(),
158	                            start_session = sorted.FirstOrDefault() ?? "0",
159	                            end_session = sorted.LastOrDefault() ?? "0"
160	                        };
161	                    })
162	                );
163	                course.UpdatedAt = DateTime.UtcNow;
164	            }
165	
166	            await db.SaveChangesAsync();
167	        }
168	    }
169	
170	    /// <summary>
171	    /// Fill NameEn for every stored course via https://course.ntu.edu.tw/api/v3/course?semester={semester}&serial={serial}&lang=en_US.
172	    /// </summary>
173	    private async Task SyncEnglishNamesAsync(HttpClient httpClient)
174	    {
175	        await using var db = await _dbFactory.CreateDbContextAsync();
176	        var courses = await db.Courses
177	            .Where(c => !string.IsNullOrEmpty(c.Serial))
178	            .ToListAsync();
179	
180	        foreach (var course in courses)
181	        {
