1	using FutureClassroom.Api.Models;
2	using FutureClassroom.Api.Services;
3	using FutureClassroom.Core.Data;
4	using FutureClassroom.Core.Extension;
5	using FutureClassroom.Core.Helpers;
6	using Microsoft.EntityFrameworkCore;
7	using System.IO.Compression;
8	using System.Text.Json;
9	
10	namespace FutureClassroom.Api.Endpoints;
11	
12	public static class AiResultEndpoints
13	{
14	    public static void MapAiResultApi(this WebApplication app)
15	    {
16	
17	        var group = app.MapGroup("/ai");
18	
19	        /// <summary>
20	        /// 上傳課程互動Json壓縮檔-zip
21	        /// </summary>
22	        /// <returns></returns>
23	        group.MapPost("/result", async (HttpRequest request, AppDbContext db, ILogger<AiResult> logger) =>
24	        {
25	            string rawJson;
26	            try
27	            {
28	                using var ms = new MemoryStream();
29	
30	                if (request.HasFormContentType)
31	                {
32	                    var form = await request.ReadFormAsync();
33	                    var file = form.Files.FirstOrDefault();
34	                    if (file is null)
35	                        return ApiErrors.InvalidParameter("No file found in the multipart form.");
36	                    await file.CopyToAsync(ms);
37	                }
38	                else
39	                {
40	                    await request.Body.CopyToAsync(ms);
41	                }
42	
43	                ms.Position = 0;
44	                using var zipArchive = new ZipArchive(ms, ZipArchiveMode.Read, leaveOpen: false);
45	                var jsonEntry = zipArchive.Entries.FirstOrDefault(e =>
46	                    e.FullName.EndsWith(".json", StringComparison.OrdinalIgnoreCase));
47	
48	                if (jsonEntry is null)
49	                    return ApiErrors.InvalidParameter("No JSON file found in the zip archive.");
50	
51	                using var entryStream = jsonEntry.Open();
52	                using var reader = new StreamReader(entryStream);
53	                rawJson = await reader.ReadToEndAsync();
54	            }
55	            catch (InvalidDataException ex) {
56	                return ApiErrors.InvalidParameter($"Invalid zip archive: {ex.Message}");
57	            }
58	
59	            if (string.IsNullOrWhiteSpace(rawJson))
60	                return ApiErrors.InvalidParameter("Json is empty.");
61	
62	            AiRawRequest aiRaw;
63	            try {
64	                aiRaw = JsonSerializer.Deserialize<AiRawRequest>(rawJson,
65	                    new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
66	                    ?? throw new JsonException("Null result");
67	            }
68	            catch (Exception ex) {
69	                return ApiErrors.InvalidParameter($"Invalid JSON: {ex.Message}");
70	            }
71	
72	            var meta     = aiRaw.Metadata;            
73	            var courseId = meta.CourseId.Length switch
74	            {
75	                >= 9 => $"{meta.CourseId[..3]} {meta.CourseId[4..]}",
76	                8    => $"{meta.CourseId[..3]} {meta.CourseId[3..]}",
77	                _    => meta.CourseId
78	            };
79	
80	            // Look up the NTU-format CourseKey from DB (e.g. "1142_502 20002_04" with space).
81	            // Fall back to constructing from AI fields if course not yet synced.
82	            var courseKey = await db.Courses
83	                .Where(c => c.Semester == meta.Semester && c.CourseId == courseId && c.Section == meta.ClassSection)
84	                .Select(c => c.CourseKey)
85	                .FirstOrDefaultAsync()
86	                ?? $"{meta.Semester}_{courseId}_{meta.ClassSection}";
87	
88	            var lessonId = CourseHelper.BuildLessonId(courseKey, meta.Week.ToInt(), meta.GeneratedAt!.ToDateTime());             
89	
90	            // Upsert structured metadata — one row per lesson
91	            var aiResult = await db.AiResults.FirstOrDefaultAsync(r => r.LessonId == lessonId);
92	            if (aiResult is null) {
93	                aiResult = new AiResult { LessonId = lessonId, CourseKey = courseKey };
94	                db.AiResults.Add(aiResult);
95	            }
96	
97	            aiResult.Semester             = meta.Semester;
98	            aiResult.CourseId             = courseId;
99	            aiResult.ClassSection         = meta.ClassSection;
100	            aiResult.Week                 = meta.Week;
101	            aiResult.GeneratedAt          = meta.GeneratedAt is not null ? DateTime.SpecifyKind(DateTimeOffset.Parse(meta.GeneratedAt).DateTime, DateTimeKind.Utc) : null;
102	            aiResult.WindowSeconds        = meta.WindowSeconds;
103	            aiResult.TotalWindows         = aiRaw.Windows.Count;
104	           
105	            var expectedGroups = new List<string> { "G1", "G2", "G3", "G4", "G5", "G6" };
106	            var completedGroups = meta.RecognizedGroups;
107	            var missingGroups = expectedGroups.Except(completedGroups).ToList();
108	
109	            aiResult.ExpectedGroupsJson    = JsonSerializer.Serialize(expectedGroups);
110	            aiResult.CompletedGroupsJson   = JsonSerializer.Serialize(completedGroups);
111	            aiResult.MissingGroupsJson     = JsonSerializer.Serialize(missingGroups);
112	            aiResult.RecordDate            = meta.RecordDate is not null ? DateOnly.Parse(meta.RecordDate) : null;
113	            aiResult.LessonDate            = meta.LessonDate is not null ? DateOnly.Parse(meta.LessonDate) : null;
114	            aiResult.UpdatedAt             = DateTime.UtcNow;
115	            
116	            await db.AiWindowSeats
117	                .Where(s => s.LessonId == lessonId)
118	                .ExecuteDeleteAsync();
119	
120	            await db.AiWindows
121	                .Where(w => w.LessonId == lessonId)
122	                .ExecuteDeleteAsync();
123	
124	            foreach (var win in aiRaw.Windows) {
125	                db.AiWindows.Add(new AiWindow {
126	                    LessonId     = lessonId,
127	                    WindowIndex  = win.WindowIndex,
128	                    StartSeconds = win.StartSeconds,
129	                    EndSeconds   = win.EndSeconds,
130	                    GroupCount   = win.GroupCount,
131	                });
132	            }
133	            
134	            await db.SaveChangesAsync();
135	          
136	            var engagementLevels = meta.EngagementValues;
137	
138	            foreach (var win in aiRaw.Windows) {
139	                foreach (var (seatKey, levels) in win.GetSeats()) {
140	                    var groupKey = seatKey.Contains('_') ? seatKey[..seatKey.IndexOf('_')] : seatKey;
141	                    foreach (var level in engagementLevels) {
142	                        var levelStr = level.ToString();
143	                        db.AiWindowSeats.Add(new AiWindowSeat {
144	                            LessonId        = lessonId,
145	                            WindowIndex     = win.WindowIndex,
146	                            SeatKey         = seatKey,
147	                            GroupKey        = groupKey,
148	                            EngagementLevel = levelStr,
149	                            Value           = levels.GetValueOrDefault(levelStr),
150	                        });
151	                    }
152	                }
153	            }
154	            
155	            await db.SaveChangesAsync();
156	
157	            return Results.Ok(new {
158	                lessonId,
159	                windows  = aiRaw.Windows.Count,
160	                complete = meta.Complete,
161	            });
162	        }).WithSummary("上傳課程互動Json壓縮檔-zip");
163	    }
164	}
