127	    private async Task<LessonResultDto?> BuildResultFromDbAsync(string lessonId, CancellationToken ct)
128	    {
129	        var windows = await db.AiWindows
130	            .AsNoTracking()
131	            .Where(w => w.LessonId == lessonId)
132	            .OrderBy(w => w.WindowIndex)
133	            .ToListAsync(ct);
134	
135	        if (windows.Count == 0) return null;
136	
137	        var seats = await db.AiWindowSeats
138	            .AsNoTracking()
139	            .Where(s => s.LessonId == lessonId)
140	            .ToListAsync(ct);
141	
142	        // group seats by (WindowIndex, SeatKey) for fast lookup
143	        var seatsByWindow = seats
144	            .GroupBy(s => s.WindowIndex)
145	            .ToDictionary(
146	                g => g.Key,
147	                g => g.GroupBy(s => s.SeatKey)
148	                      .ToDictionary(
149	                          sg => sg.Key,
150	                          sg => sg.ToDictionary(s => s.EngagementLevel, s => s.Value)
151	                      )
152	            );
153	
154	        var classSlices = new List<EngagementSliceDto>();
155	        var groupSlices = new Dictionary<string, List<EngagementSliceDto>>();
156	
157	        foreach (var win in windows)
158	        {
159	            if (!seatsByWindow.TryGetValue(win.WindowIndex, out var winSeats)) continue;
160	
161	            var byGroup = winSeats
162	                .GroupBy(kvp => kvp.Key.Contains('_') ? kvp.Key[..kvp.Key.IndexOf('_')] : kvp.Key)
163	                .ToDictionary(g => g.Key, g => g.Select(kvp => kvp.Value).ToList());
164	
165	            // class average: average across all seats in this window
166	            var allSeatLevels = winSeats.Values.ToList();
167	            classSlices.Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(allSeatLevels)));
168	
169	            // group (table) averages
170	            foreach (var (groupKey, seatLevels) in byGroup)
171	            {
172	                if (!groupSlices.ContainsKey(groupKey))
173	                    groupSlices[groupKey] = [];
174	                groupSlices[groupKey].Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(seatLevels)));
175	            }
176	        }
177	
178	        return new LessonResultDto(groupSlices, classSlices);
179	    }
