20	            try {
21	                var callbackUrl = $"{fcOpt.Value.BaseUrl}auth/callback";
22	
23	                var props = new AuthenticationProperties { RedirectUri = callbackUrl };
24	                await context.ChallengeAsync(Saml2Defaults.Scheme, props);
25	            }
26	            catch {
27	                Results.Problem("Failed to initialize login flow.", statusCode: 500);
28	            }
29	        });
30	    
31	        group.MapGet("/callback", async Task<IResult> (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
32	            var result = await context.AuthenticateAsync(AuthScheme);
33	            if (!result.Succeeded)
34	                return ApiErrors.Unauthorized("SSO authentication failed.");
35	
36	            var claimsIdentity = result.Principal?.Identity as System.Security.Claims.ClaimsIdentity;
37	            var ntuAccountName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountName")?.Value;
