65	                });
66	            });
67	        }
68	
69	        group.MapGet("/logout", async Task<IResult> (
70	            HttpContext context,
71	            IWebHostEnvironment env,
72	            IOptions<NtuSsoOptions> ssoOpt,
73	            IOptions<FutureClassroomOptions> fcOpt) => {
74	
75	            await context.SignOutAsync(AuthScheme);
76	
77	            var returnUrl = $"{fcOpt.Value.FrontendUrl}login";
78	
79	            if (env.IsDevelopment())
80	                return Results.Redirect(returnUrl); // 在本機開發時導回本地端登入頁
