92	            var id = context.User.FindFirst("StudentId")?.Value;
93	            var name = context.User.FindFirst(ClaimTypes.Name)?.Value;
94	            var department = context.User.FindFirst("Major")?.Value;
95	            var role = context.User.FindFirst("UserType")?.Value;
96	
97	            var resolved = await departments.FindByMajorAsync(department);
98	
99	            return Results.Ok(new UserResponse(
100	                User: new UserInfo(
101	                    Id: id ?? "",
102	                    Name: name ?? "",
103	                    Department: department,
104	                    DepartmentZh: resolved?.NameZh ?? department,
105	                    DepartmentEn: resolved?.NameEn ?? department,
106	                    Role: role ?? ""
107	                )
108	            ));
109	        }); 
110	 
111	    }
