299	              <div className="text-center py-12 text-slate-400 bg-white rounded-2xl">
300	                {/* {!isLoading && searchKeyword
301	                  ? t("course.noResults", { keyword: searchKeyword })
302	                  : t("course.loading")} */}
303	                {isLoading
304	                  ? t("course.loading")
305	                  : searchKeyword
306	                    ? t("course.noResults", { keyword: searchKeyword })
307	                    : t("course.noCoursesTitle")}
308	              </div>
309	            )}
310	          </div>
311	        </section>
312	      </div>
313	    </div>
314	  );
315	}
