23	});
24	
25	
26	builder.Services.Configure<NtuSsoOptions>(builder.Configuration.GetSection("NtuSso"));
27	builder.Services.Configure<FutureClassroomOptions>(builder.Configuration.GetSection("FutureClassroomApi"));
28	
29	builder.Services.AddDbContext<AppDbContext>(opt =>
30	    opt.UseNpgsql(builder.Configuration.GetConnectionString("Default"),
31	        npgsql => npgsql.MigrationsAssembly(typeof(Program).Assembly.FullName)));
32	
33	
34	builder.Services.AddKeyedSingleton<IAmazonS3>("s3", (_, _) =>
35	{
36	    var s3Config = builder.Configuration.GetSection("S3");
37	    return new AmazonS3Client(s3Config["AccessKey"] ?? "", s3Config["SecretKey"] ?? "", new AmazonS3Config
38	    {
39	        ServiceURL = s3Config["ServiceUrl"],
40	        ForcePathStyle = true,
41	        AuthenticationRegion = "us-east-1",
42	        HttpClientFactory = new BypassSslHttpClientFactory()
43	    });
