53	
54	
55	var ntuSsoOptions = builder.Configuration.GetSection("NtuSso").Get<NtuSsoOptions>()!;
56	var fcOptions = builder.Configuration.GetSection("FutureClassroomApi").Get<FutureClassroomOptions>()!;
57	var baseUrlPath = builder.Configuration.GetValue<string>("BaseUrlPath")!;
58	
59	var baseUrl = fcOptions.BaseUrl;
