61	
62	builder.Services.AddDataProtection()
63	    .PersistKeysToDbContext<AppDbContext>()
64	    .SetApplicationName(baseUrlPath);
65	
66	builder.Services.AddAuthentication(options => {
67	    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
68	    options.DefaultChallengeScheme = Saml2Defaults.Scheme;
69	})
70	.AddCookie(options => {
71	    options.Cookie.Name = $"_{baseUrlPath}";
72	    options.ExpireTimeSpan = TimeSpan.FromHours(8);
73	    options.LoginPath = "/auth/login";
74	    options.Events.OnRedirectToLogin = ctx => {
75	        ctx.Response.StatusCode = 401;
76	        return Task.CompletedTask;
77	    };
78	    options.Events.OnRedirectToAccessDenied = ctx => {
79	        ctx.Response.StatusCode = 403;
80	        return Task.CompletedTask;
81	    };
82	})
83	.AddSaml2(options => {
84	    var env = builder.Environment;
85	    var certPath = Path.Combine(env.ContentRootPath, "App_Data", "sso.pfx");
86	
87	    options.SPOptions.NameIdPolicy = new Saml2NameIdPolicy(true, NameIdFormat.Unspecified);
88	    options.SPOptions.EntityId = new EntityId(baseUrl);
89	    options.SPOptions.PublicOrigin = new Uri(baseUrl);
90	
91	    if (File.Exists(certPath))
